def calc(expr: str) -> int | str:
    n = len(expr)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q, r = divmod(a, b)
        if r and (a < 0) != (b < 0):
            q += 1
        return q

    def parse_primary() -> int | str:
        nonlocal i
        skip()
        if expr[i] == "(":
            i += 1
            val = parse_expr()
            if val == "error":
                return "error"
            skip()
            i += 1
            return val
        start = i
        while i < n and expr[i].isdigit():
            i += 1
        return int(expr[start:i])

    def parse_unary() -> int | str:
        nonlocal i
        nodes: list[tuple[int, int]] = []
        while True:
            skip()
            sign = 1
            while i < n and expr[i] == "-":
                sign = -sign
                i += 1
                skip()
            base = parse_primary()
            if base == "error":
                return "error"
            nodes.append((sign, base))
            skip()
            if i < n and expr[i] == "^":
                i += 1
                continue
            break
        sign, base = nodes[-1]
        acc = sign * base
        for sign, base in reversed(nodes[:-1]):
            if acc < 0:
                return "error"
            acc = sign * pow(base, acc)
        return acc

    def parse_term() -> int | str:
        nonlocal i
        left = parse_unary()
        if left == "error":
            return "error"
        while True:
            skip()
            if i < n and expr[i] in "*/%":
                op = expr[i]
                i += 1
                right = parse_unary()
                if right == "error":
                    return "error"
                if op == "*":
                    left = left * right
                elif right == 0:
                    return "error"
                elif op == "/":
                    left = trunc_div(left, right)
                else:
                    left = left - right * trunc_div(left, right)
            else:
                return left

    def parse_expr() -> int | str:
        nonlocal i
        left = parse_term()
        if left == "error":
            return "error"
        while True:
            skip()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                right = parse_term()
                if right == "error":
                    return "error"
                left = left + right if op == "+" else left - right
            else:
                return left

    return parse_expr()
